insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A1-008', 'M1-A1-K3', 'numeric', 2, '気温の差', '{"id": "T-M1-A1-008", "item": "M1-A1", "item_kind": "knowledge", "item_index": 3, "format": "numeric", "difficulty": 2, "title": "気温の差", "variables": {"t2": {"type": "int", "min": -9, "max": 5}, "d": {"type": "int", "min": 1, "max": 15}}, "constraints": [], "derived": {"t1": "t2 + d", "ans": "d"}, "body": "ある日の最高気温は {t1}℃、最低気温は {t2}℃ でした。\nこの日の気温の差は何℃ですか。", "answers": {"差": "ans"}, "explanation": "気温の差は (最高気温) - (最低気温) で求めます。\n{t1} - ({t2}) = {ans}（℃）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A1-009', 'M1-A1-T1', 'choice', 1, '計算結果の符号', '{"id": "T-M1-A1-009", "item": "M1-A1", "item_kind": "thinking", "item_index": 1, "format": "choice", "difficulty": 1, "title": "計算結果の符号", "variables": {"q": {"type": "int", "min": 1, "max": 4}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "（負の数）＋（負の数）の答えの符号はどれですか。", "2": "（負の数）×（負の数）の答えの符号はどれですか。", "3": "（正の数）×（負の数）の答えの符号はどれですか。", "4": "（負の数）÷（負の数）の答えの符号はどれですか。"}, "correct_by_case": {"1": "負", "2": "正", "3": "負", "4": "正"}, "distractors_by_case": {"1": ["正", "0", "場合による"], "2": ["負", "0", "場合による"], "3": ["正", "0", "場合による"], "4": ["負", "0", "場合による"]}, "explanation": "同符号どうしの積・商は正、異符号どうしの積・商は負になります。\n負の数どうしの和は、絶対値の和に負の符号がついて負になります。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A1-010', 'M1-A1-T2', 'numeric', 2, '基準を決めた処理', '{"id": "T-M1-A1-010", "item": "M1-A1", "item_kind": "thinking", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "基準を決めた処理", "variables": {"base": {"type": "int", "min": 60, "max": 80}, "a": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "b": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "c": {"type": "int", "min": -9, "max": 9, "exclude": [0]}}, "constraints": [], "derived": {"total": "a + b + c", "ans": "base * 3 + a + b + c"}, "body": "3人のテストの得点を、{base}点を基準として表すと {a}, {b}, {c} でした。\n3人の合計得点を求めなさい。", "answers": {"合計": "ans"}, "explanation": "基準からの差の合計は {a} + ({b}) + ({c}) = {total} です。\n合計得点は {base} × 3 + ({total}) = {ans}（点）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A2-001', 'M1-A2-K2', 'choice', 1, '文字式の表し方', '{"id": "T-M1-A2-001", "item": "M1-A2", "item_kind": "knowledge", "item_index": 2, "format": "choice", "difficulty": 1, "title": "文字式の表し方", "variables": {"q": {"type": "int", "min": 1, "max": 4}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "a × 3 を、記号×を使わずに表すとどうなりますか。", "2": "x ÷ 5 を、記号÷を使わずに表すとどうなりますか。", "3": "a × a を、記号×を使わずに表すとどうなりますか。", "4": "1 × y を、記号×を使わずに表すとどうなりますか。"}, "correct_by_case": {"1": "3a", "2": "x/5", "3": "a²", "4": "y"}, "distractors_by_case": {"1": ["a3", "3+a", "a÷3"], "2": ["5/x", "5x", "x-5"], "3": ["2a", "aa", "a+a"], "4": ["1y", "y1", "y+1"]}, "explanation": "文字式では×を省き、数を文字の前に書きます。÷は分数の形で表し、同じ文字の積は累乗の指数で表します。係数の1は省略します。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A2-002', 'M1-A2-K3', 'numeric', 1, '一次式の加法', '{"id": "T-M1-A2-002", "item": "M1-A2", "item_kind": "knowledge", "item_index": 3, "format": "numeric", "difficulty": 1, "title": "一次式の加法", "variables": {"a": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "b": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "c": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "d": {"type": "int", "min": -9, "max": 9, "exclude": [0]}}, "constraints": [], "derived": {"kx": "a + c", "kc": "b + d"}, "body": "次の式を計算した結果について、xの係数と定数項を答えなさい。\n({a}x + ({b})) + ({c}x + ({d}))", "answers": {"xの係数": "kx", "定数項": "kc"}, "explanation": "同類項どうしをまとめます。\nxの項: {a}x + {c}x = {kx}x\n定数項: ({b}) + ({d}) = {kc}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A2-003', 'M1-A2-K3', 'numeric', 2, '一次式の減法', '{"id": "T-M1-A2-003", "item": "M1-A2", "item_kind": "knowledge", "item_index": 3, "format": "numeric", "difficulty": 2, "title": "一次式の減法", "variables": {"a": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "b": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "c": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "d": {"type": "int", "min": -9, "max": 9, "exclude": [0]}}, "constraints": [], "derived": {"kx": "a - c", "kc": "b - d"}, "body": "次の式を計算した結果について、xの係数と定数項を答えなさい。\n({a}x + ({b})) - ({c}x + ({d}))", "answers": {"xの係数": "kx", "定数項": "kc"}, "explanation": "かっこの前が - のときは、かっこの中の各項の符号を変えてから同類項をまとめます。\nxの項: {a}x - {c}x = {kx}x\n定数項: ({b}) - ({d}) = {kc}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A2-004', 'M1-A2-K4', 'numeric', 1, '式の値', '{"id": "T-M1-A2-004", "item": "M1-A2", "item_kind": "knowledge", "item_index": 4, "format": "numeric", "difficulty": 1, "title": "式の値", "variables": {"a": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "b": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "x0": {"type": "int", "min": -9, "max": 9, "exclude": [0]}}, "constraints": [], "derived": {"ans": "a * x0 + b"}, "body": "x = {x0} のとき、次の式の値を求めなさい。\n{a}x + ({b})", "answers": {"値": "ans"}, "explanation": "xに {x0} を代入します。\n{a} × ({x0}) + ({b}) = {ans}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A2-005', 'M1-A2-K1', 'choice', 1, '文字を使う意味', '{"id": "T-M1-A2-005", "item": "M1-A2", "item_kind": "knowledge", "item_index": 1, "format": "choice", "difficulty": 1, "title": "文字を使う意味", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "文字を使って数量を表すよさとして正しいものはどれですか。", "2": "式 2n + 1（nは整数）が表しているのはどれですか。", "3": "式 2n（nは整数）が表しているのはどれですか。"}, "correct_by_case": {"1": "数量の関係を一般的に表せる", "2": "奇数", "3": "偶数"}, "distractors_by_case": {"1": ["計算が必ず速くなる", "答えが必ず整数になる", "図をかかずに済む"], "2": ["偶数", "素数", "自然数すべて"], "3": ["奇数", "負の数", "小数"]}, "explanation": "文字を使うと、いろいろな数にあてはまる関係を1つの式で一般的に表せます。\nnを整数とすると 2n は偶数、2n + 1 は奇数を表します。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A2-006', 'M1-A2-K4', 'numeric', 2, '数量を式に表す', '{"id": "T-M1-A2-006", "item": "M1-A2", "item_kind": "knowledge", "item_index": 4, "format": "numeric", "difficulty": 2, "title": "数量を式に表す", "variables": {"a": {"type": "int", "min": 30, "max": 150}, "b": {"type": "int", "min": 50, "max": 300}}, "constraints": [], "derived": {"kx": "a", "kc": "b"}, "body": "1本 {a}円の鉛筆を x 本と、{b}円のノートを1冊買いました。\n代金の合計を x を使った式で表したとき、xの係数と定数項を答えなさい。", "answers": {"xの係数": "kx", "定数項": "kc"}, "explanation": "鉛筆の代金は {a} × x = {a}x（円）、ノートは {b}円です。\n合計は {a}x + {b}（円）なので、xの係数は {kx}、定数項は {kc} です。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A2-007', 'M1-A2-T1', 'choice', 1, '同類項をまとめる根拠', '{"id": "T-M1-A2-007", "item": "M1-A2", "item_kind": "thinking", "item_index": 1, "format": "choice", "difficulty": 1, "title": "同類項をまとめる根拠", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "3x + 2x = 5x とまとめられるのはなぜですか。", "2": "3x + 2 をこれ以上まとめられないのはなぜですか。", "3": "2x + 3y をこれ以上まとめられないのはなぜですか。"}, "correct_by_case": {"1": "分配法則が成り立つから", "2": "3xと2は同類項ではないから", "3": "文字が異なり同類項ではないから"}, "distractors_by_case": {"1": ["文字が同じだから偶然そうなる", "xが1だから", "係数をたす決まりだから"], "2": ["3と2が違う数だから", "xの値が分からないから", "式が短いから"], "3": ["係数が異なるから", "xとyの大きさが違うから", "項が2つだけだから"]}, "explanation": "3x + 2x は分配法則 (3 + 2)x = 5x により1つの項にまとめられます。\n文字の部分が同じ項（同類項）だけをまとめることができます。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A2-008', 'M1-A2-K3', 'numeric', 2, '一次式と数の乗法', '{"id": "T-M1-A2-008", "item": "M1-A2", "item_kind": "knowledge", "item_index": 3, "format": "numeric", "difficulty": 2, "title": "一次式と数の乗法", "variables": {"k": {"type": "int", "min": -9, "max": 9, "exclude": [0, 1]}, "a": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "b": {"type": "int", "min": -9, "max": 9, "exclude": [0]}}, "constraints": [], "derived": {"kx": "k * a", "kc": "k * b"}, "body": "次の式を計算した結果について、xの係数と定数項を答えなさい。\n{k}({a}x + ({b}))", "answers": {"xの係数": "kx", "定数項": "kc"}, "explanation": "分配法則を使って、かっこの中の各項に {k} をかけます。\nxの項: {k} × {a}x = {kx}x\n定数項: {k} × ({b}) = {kc}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A3-001', 'M1-A3-K2', 'numeric', 1, '一元一次方程式（ax+b=c）', '{"id": "T-M1-A3-001", "item": "M1-A3", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 1, "title": "一元一次方程式（ax+b=c）", "variables": {"a": {"type": "int", "min": 2, "max": 9}, "x0": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "b": {"type": "int", "min": -9, "max": 9, "exclude": [0]}}, "constraints": [], "derived": {"c": "a * x0 + b", "ax": "a * x0"}, "body": "次の方程式を解きなさい。\n{a}x + ({b}) = {c}", "answers": {"x": "x0"}, "explanation": "({b}) を移項します。\n{a}x = {c} - ({b}) = {ax}\n両辺を {a} でわって x = {x0}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A3-002', 'M1-A3-K2', 'numeric', 2, '一元一次方程式（両辺に文字）', '{"id": "T-M1-A3-002", "item": "M1-A3", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "一元一次方程式（両辺に文字）", "variables": {"a": {"type": "int", "min": 2, "max": 9}, "c": {"type": "int", "min": 2, "max": 9}, "x0": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "b": {"type": "int", "min": -9, "max": 9, "exclude": [0]}}, "constraints": ["a != c"], "derived": {"ac": "a - c", "d": "(a - c) * x0 + b", "acx": "(a - c) * x0"}, "body": "次の方程式を解きなさい。\n{a}x + ({b}) = {c}x + ({d})", "answers": {"x": "x0"}, "explanation": "文字の項を左辺に、数の項を右辺に移項します。\n{a}x - {c}x = {d} - ({b})\n{ac}x = {acx}\n両辺を {ac} でわって x = {x0}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A3-003', 'M1-A3-K1', 'choice', 1, '方程式と解の意味', '{"id": "T-M1-A3-003", "item": "M1-A3", "item_kind": "knowledge", "item_index": 1, "format": "choice", "difficulty": 1, "title": "方程式と解の意味", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "方程式の「解」とは何ですか。", "2": "等式の性質として正しいものはどれですか。", "3": "「移項」とは何をすることですか。"}, "correct_by_case": {"1": "式を成り立たせる文字の値", "2": "両辺に同じ数をたしても等式は成り立つ", "3": "項の符号を変えて他方の辺に移すこと"}, "distractors_by_case": {"1": ["式に出てくる文字", "式の左辺の値", "計算の途中の式"], "2": ["両辺に別々の数をたしてもよい", "両辺を0でわってもよい", "左辺だけを2倍してもよい"], "3": ["項を消すこと", "項をそのまま移すこと", "両辺を入れかえること"]}, "explanation": "解とは、その値を代入すると等式が成り立つ文字の値です。\n等式の性質（両辺に同じ数をたす・ひく・かける、0でない同じ数でわる）を使って解きます。\n移項は、等式の性質から導かれる操作で、符号を変えて反対側の辺へ移します。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A3-004', 'M1-A3-T1', 'choice', 1, '方程式を解く手順の根拠', '{"id": "T-M1-A3-004", "item": "M1-A3", "item_kind": "thinking", "item_index": 1, "format": "choice", "difficulty": 1, "title": "方程式を解く手順の根拠", "variables": {"q": {"type": "int", "min": 1, "max": 2}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "3x = 12 の両辺を3でわってよいのはなぜですか。", "2": "x + 5 = 8 で、5を移項して x = 8 - 5 としてよいのはなぜですか。"}, "correct_by_case": {"1": "両辺を同じ数でわっても等式は成り立つから", "2": "両辺から同じ数をひいても等式は成り立つから"}, "distractors_by_case": {"1": ["3が一番小さい数だから", "12が3の倍数だから", "xの係数を1にする決まりだから"], "2": ["5が右辺より小さいから", "移項は必ずできる決まりだから", "左辺を先に計算するから"]}, "explanation": "方程式を解く操作は、すべて等式の性質にもとづいています。\n両辺に同じ数をたす・ひく・かける、0でない同じ数でわる、という操作で解を求めます。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A3-005', 'M1-A3-T2', 'numeric', 2, '方程式の活用（代金）', '{"id": "T-M1-A3-005", "item": "M1-A3", "item_kind": "thinking", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "方程式の活用（代金）", "variables": {"a": {"type": "int", "min": 50, "max": 200}, "b": {"type": "int", "min": 50, "max": 300}, "x0": {"type": "int", "min": 2, "max": 12}}, "constraints": [], "derived": {"c": "a * x0 + b", "ax": "a * x0"}, "body": "1個 {a}円のりんごを x 個買い、{b}円の箱に入れてもらったところ、\n代金の合計は {c}円でした。りんごを何個買いましたか。", "answers": {"個数": "x0"}, "explanation": "代金の関係を式にすると {a}x + {b} = {c} です。\n{a}x = {c} - {b} = {ax}\nx = {x0}（個）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A3-006', 'M1-A3-T2', 'numeric', 2, '方程式の活用（過不足）', '{"id": "T-M1-A3-006", "item": "M1-A3", "item_kind": "thinking", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "方程式の活用（過不足）", "variables": {"a": {"type": "int", "min": 3, "max": 8}, "x0": {"type": "int", "min": 4, "max": 15}, "r": {"type": "int", "min": 1, "max": 9}}, "constraints": ["(a + 1) * x0 - (a * x0 + r) > 0"], "derived": {"total": "a * x0 + r", "b": "a + 1", "d": "(a + 1) * x0 - (a * x0 + r)"}, "body": "画用紙を何人かの子どもに配ります。\n1人に {a}枚ずつ配ると {r}枚あまり、1人に {b}枚ずつ配ると {d}枚たりません。\n子どもの人数を求めなさい。", "answers": {"人数": "x0"}, "explanation": "子どもの人数を x 人とすると、画用紙の枚数は {a}x + {r} とも {b}x - {d} とも表せます。\n{a}x + {r} = {b}x - {d} を解いて x = {x0}（人）\n（画用紙は {total}枚です）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A3-007', 'M1-A3-K2', 'numeric', 2, '比例式', '{"id": "T-M1-A3-007", "item": "M1-A3", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "比例式", "variables": {"k": {"type": "int", "min": 2, "max": 8}, "a": {"type": "int", "min": 1, "max": 9}, "b": {"type": "int", "min": 1, "max": 9}}, "constraints": [], "derived": {"c": "a * k", "ans": "b * k"}, "body": "次の比例式で、x にあてはまる数を求めなさい。\n{a} : {b} = {c} : x", "answers": {"x": "ans"}, "explanation": "比例式では、外側の項の積と内側の項の積が等しくなります。\n{a} × x = {b} × {c}\nx = {ans}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-B1-001', 'M1-B1-K1', 'choice', 1, '基本の作図', '{"id": "T-M1-B1-001", "item": "M1-B1", "item_kind": "knowledge", "item_index": 1, "format": "choice", "difficulty": 1, "title": "基本の作図", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "線分ABの垂直二等分線上にある点はどんな点ですか。", "2": "∠AOBの二等分線上にある点はどんな点ですか。", "3": "直線ℓ上にない点Pから、ℓへ垂線をひいたとき、交点までの長さは何を表しますか。"}, "correct_by_case": {"1": "2点A, Bから等しい距離にある点", "2": "2辺OA, OBから等しい距離にある点", "3": "点Pと直線ℓとの距離"}, "distractors_by_case": {"1": ["線分ABの中点だけ", "Aに近い側にある点", "線分AB上にある点"], "2": ["点Oから等しい距離にある点", "∠AOBの外側の点", "辺OA上の点"], "3": ["点Pと原点との距離", "直線ℓの長さ", "垂線の傾き"]}, "explanation": "垂直二等分線は2点から等距離にある点の集まり、角の二等分線は角の2辺から等距離にある点の集まりです。\n点と直線の距離は、点から直線にひいた垂線の長さで表します。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-B1-002', 'M1-B1-K2', 'choice', 1, '図形の移動', '{"id": "T-M1-B1-002", "item": "M1-B1", "item_kind": "knowledge", "item_index": 2, "format": "choice", "difficulty": 1, "title": "図形の移動", "variables": {"q": {"type": "int", "min": 1, "max": 4}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "図形を一定の方向に、一定の長さだけずらす移動を何といいますか。", "2": "図形を1つの直線を折り目として折り返す移動を何といいますか。", "3": "図形を1つの点を中心として、一定の角度だけまわす移動を何といいますか。", "4": "180°の回転移動を特に何といいますか。"}, "correct_by_case": {"1": "平行移動", "2": "対称移動", "3": "回転移動", "4": "点対称移動"}, "distractors_by_case": {"1": ["対称移動", "回転移動", "拡大移動"], "2": ["平行移動", "回転移動", "点対称移動"], "3": ["平行移動", "対称移動", "平行四辺形移動"], "4": ["線対称移動", "平行移動", "対称移動"]}, "explanation": "移動は平行移動・対称移動・回転移動の3つに分けられます。\n回転移動のうち、回転角が180°のものを特に点対称移動といいます。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-B1-003', 'M1-B1-K2', 'numeric', 2, '回転移動の角度', '{"id": "T-M1-B1-003", "item": "M1-B1", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "回転移動の角度", "variables": {"a": {"type": "int", "min": 1, "max": 35}}, "constraints": [], "derived": {"deg": "10 * a", "ans": "360 - 10 * a"}, "body": "点Oを中心として、時計回りに {deg}° 回転移動しました。\nこれは反時計回りに何度回転移動したことと同じですか。", "answers": {"角度": "ans"}, "explanation": "1回転は360°です。時計回りに {deg}° 回すことは、\n反時計回りに 360 - {deg} = {ans}（°）回すことと同じになります。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-B1-004', 'M1-B1-T1', 'choice', 1, '作図の方法を考える', '{"id": "T-M1-B1-004", "item": "M1-B1", "item_kind": "thinking", "item_index": 1, "format": "choice", "difficulty": 1, "title": "作図の方法を考える", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "2点A, Bから等しい距離にある点を作図するには、何をかけばよいですか。", "2": "角を2等分する半直線を作図するには、何を利用しますか。", "3": "円の接線をかくとき、接点を通る半径と接線の関係はどうなりますか。"}, "correct_by_case": {"1": "線分ABの垂直二等分線", "2": "角の二等分線の作図", "3": "垂直に交わる"}, "distractors_by_case": {"1": ["線分ABの延長", "点Aを中心とする円だけ", "∠Aの二等分線"], "2": ["垂直二等分線の作図", "円の接線の作図", "平行線の作図"], "3": ["平行になる", "45°に交わる", "重なる"]}, "explanation": "求める点や線がもつ性質に着目すると、どの作図を使えばよいかが決まります。\n円の接線は、その接点を通る半径に垂直です。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-B1-005', 'M1-B1-T2', 'choice', 1, '移動と対応', '{"id": "T-M1-B1-005", "item": "M1-B1", "item_kind": "thinking", "item_index": 2, "format": "choice", "difficulty": 1, "title": "移動と対応", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "平行移動で、対応する2点を結んだ線分どうしの関係はどうなりますか。", "2": "対称移動で、対応する2点を結ぶ線分と対称の軸の関係はどうなりますか。", "3": "回転移動で、対応する2点と回転の中心Oまでの距離はどうなりますか。"}, "correct_by_case": {"1": "平行で長さが等しい", "2": "対称の軸が線分を垂直に2等分する", "3": "等しい"}, "distractors_by_case": {"1": ["垂直に交わる", "1点で交わる", "長さが2倍になる"], "2": ["対称の軸と平行になる", "対称の軸と重なる", "関係はない"], "3": ["2倍になる", "半分になる", "回転角によって変わる"]}, "explanation": "移動しても図形の形と大きさは変わりません。\n平行移動では対応する点を結ぶ線分が平行で等長、対称移動では対称の軸が垂直二等分線、\n回転移動では回転の中心から対応する点までの距離が等しくなります。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-B1-006', 'M1-B1-T3', 'choice', 2, '作図・移動の活用', '{"id": "T-M1-B1-006", "item": "M1-B1", "item_kind": "thinking", "item_index": 3, "format": "choice", "difficulty": 2, "title": "作図・移動の活用", "variables": {"q": {"type": "int", "min": 1, "max": 2}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "2つの町A, Bから等しい距離の地点に駅をつくるとき、どの作図を使いますか。", "2": "2本の道路のどちらからも等しい距離にある地点を求めるには、どの作図を使いますか。"}, "correct_by_case": {"1": "線分ABの垂直二等分線", "2": "2直線がつくる角の二等分線"}, "distractors_by_case": {"1": ["∠Aの二等分線", "Aを通る垂線", "ABの延長"], "2": ["垂直二等分線", "円の接線", "平行線"]}, "explanation": "「等しい距離」という条件を、垂直二等分線や角の二等分線の性質に結びつけて考えます。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-B2-001', 'M1-B2-K2', 'numeric', 1, '直方体の体積', '{"id": "T-M1-B2-001", "item": "M1-B2", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 1, "title": "直方体の体積", "variables": {"a": {"type": "int", "min": 2, "max": 12}, "b": {"type": "int", "min": 2, "max": 12}, "h": {"type": "int", "min": 2, "max": 12}}, "constraints": [], "derived": {"ans": "a * b * h"}, "body": "縦 {a}cm、横 {b}cm、高さ {h}cm の直方体の体積を求めなさい。", "answers": {"体積": "ans"}, "explanation": "直方体の体積は （縦）×（横）×（高さ）で求めます。\n{a} × {b} × {h} = {ans}（cm³）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-B2-002', 'M1-B2-K2', 'numeric', 2, '直方体の表面積', '{"id": "T-M1-B2-002", "item": "M1-B2", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "直方体の表面積", "variables": {"a": {"type": "int", "min": 2, "max": 10}, "b": {"type": "int", "min": 2, "max": 10}, "h": {"type": "int", "min": 2, "max": 10}}, "constraints": [], "derived": {"s1": "a * b", "s2": "b * h", "s3": "a * h", "ans": "2 * (a * b + b * h + a * h)"}, "body": "縦 {a}cm、横 {b}cm、高さ {h}cm の直方体の表面積を求めなさい。", "answers": {"表面積": "ans"}, "explanation": "向かい合う面が2つずつ、3種類あります。\n{a}×{b}={s1}、{b}×{h}={s2}、{a}×{h}={s3}\n表面積は 2 × ({s1} + {s2} + {s3}) = {ans}（cm²）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-B2-003', 'M1-B2-K2', 'numeric', 2, '四角錐の体積', '{"id": "T-M1-B2-003", "item": "M1-B2", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "四角錐の体積", "variables": {"a": {"type": "int", "min": 2, "max": 12}, "b": {"type": "int", "min": 2, "max": 12}, "k": {"type": "int", "min": 1, "max": 6}}, "constraints": [], "derived": {"h": "3 * k", "base": "a * b", "ans": "a * b * k"}, "body": "底面が縦 {a}cm、横 {b}cm の長方形で、高さが {h}cm の四角錐の体積を求めなさい。", "answers": {"体積": "ans"}, "explanation": "角錐の体積は （底面積）×（高さ）÷ 3 で求めます。\n底面積は {a} × {b} = {base}（cm²）\n{base} × {h} ÷ 3 = {ans}（cm³）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-B2-004', 'M1-B2-K2', 'numeric', 2, 'おうぎ形の弧の長さ', '{"id": "T-M1-B2-004", "item": "M1-B2", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "おうぎ形の弧の長さ", "variables": {"m": {"type": "int", "min": 1, "max": 4}, "j": {"type": "int", "min": 1, "max": 5}}, "constraints": [], "derived": {"r": "6 * m", "deg": "60 * j", "ans": "2 * m * j"}, "body": "半径 {r}cm、中心角 {deg}° のおうぎ形があります。\nこの弧の長さは □π cm です。□にあてはまる数を求めなさい。", "answers": {"□": "ans"}, "explanation": "おうぎ形の弧の長さは （直径）× π ×（中心角）÷ 360 で求めます。\n2 × {r} × π × {deg} ÷ 360 = {ans}π（cm）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-B2-005', 'M1-B2-K2', 'numeric', 2, 'おうぎ形の面積', '{"id": "T-M1-B2-005", "item": "M1-B2", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "おうぎ形の面積", "variables": {"m": {"type": "int", "min": 1, "max": 3}, "j": {"type": "int", "min": 1, "max": 5}}, "constraints": [], "derived": {"r": "6 * m", "deg": "60 * j", "ans": "6 * m * m * j"}, "body": "半径 {r}cm、中心角 {deg}° のおうぎ形があります。\nこの面積は □π cm² です。□にあてはまる数を求めなさい。", "answers": {"□": "ans"}, "explanation": "おうぎ形の面積は （半径）×（半径）× π ×（中心角）÷ 360 で求めます。\n{r} × {r} × π × {deg} ÷ 360 = {ans}π（cm²）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-B2-006', 'M1-B2-K1', 'choice', 1, '空間における位置関係', '{"id": "T-M1-B2-006", "item": "M1-B2", "item_kind": "knowledge", "item_index": 1, "format": "choice", "difficulty": 1, "title": "空間における位置関係", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "空間で、平行でなく交わりもしない2直線の位置関係を何といいますか。", "2": "直方体で、1つの面に垂直な辺は何本ありますか。", "3": "空間で、1つの直線とその上にない1点をふくむ平面は何個決まりますか。"}, "correct_by_case": {"1": "ねじれの位置", "2": "4本", "3": "1個"}, "distractors_by_case": {"1": ["平行", "垂直", "同一平面上"], "2": ["2本", "1本", "6本"], "3": ["2個", "無数", "0個"]}, "explanation": "空間内の2直線の位置関係は、交わる・平行・ねじれの位置の3つです。\nねじれの位置にある2直線は同じ平面上にありません。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-B2-007', 'M1-B2-T1', 'choice', 1, '立体の見方と表し方', '{"id": "T-M1-B2-007", "item": "M1-B2", "item_kind": "thinking", "item_index": 1, "format": "choice", "difficulty": 1, "title": "立体の見方と表し方", "variables": {"q": {"type": "int", "min": 1, "max": 4}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "長方形を、1つの辺を軸として1回転させてできる立体はどれですか。", "2": "直角三角形を、直角をはさむ1辺を軸として1回転させてできる立体はどれですか。", "3": "半円を、直径を軸として1回転させてできる立体はどれですか。", "4": "立体を真上から見た図を何といいますか。"}, "correct_by_case": {"1": "円柱", "2": "円錐", "3": "球", "4": "平面図"}, "distractors_by_case": {"1": ["円錐", "球", "三角柱"], "2": ["円柱", "球", "四角錐"], "3": ["円柱", "円錐", "半球"], "4": ["立面図", "展開図", "見取図"]}, "explanation": "平面図形を回転させてできる立体を回転体といいます。\n投影図では、真正面から見た図を立面図、真上から見た図を平面図といいます。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-B2-008', 'M1-B2-T2', 'numeric', 2, '円柱の体積', '{"id": "T-M1-B2-008", "item": "M1-B2", "item_kind": "thinking", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "円柱の体積", "variables": {"r": {"type": "int", "min": 1, "max": 9}, "h": {"type": "int", "min": 2, "max": 12}}, "constraints": [], "derived": {"ans": "r * r * h"}, "body": "底面の半径が {r}cm、高さが {h}cm の円柱があります。\nこの体積は □π cm³ です。□にあてはまる数を求めなさい。", "answers": {"□": "ans"}, "explanation": "円柱の体積は （底面積）×（高さ）で求めます。\n底面積は {r} × {r} × π = ({r}×{r})π（cm²）\n体積は {r} × {r} × π × {h} = {ans}π（cm³）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-B2-009', 'M1-B2-K2', 'numeric', 2, '球の表面積', '{"id": "T-M1-B2-009", "item": "M1-B2", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "球の表面積", "variables": {"r": {"type": "int", "min": 1, "max": 9}}, "constraints": [], "derived": {"ans": "4 * r * r"}, "body": "半径 {r}cm の球の表面積は □π cm² です。□にあてはまる数を求めなさい。", "answers": {"□": "ans"}, "explanation": "球の表面積は 4 ×（半径）×（半径）× π で求めます。\n4 × {r} × {r} × π = {ans}π（cm²）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-C1-001', 'M1-C1-K2', 'numeric', 1, '比例の式と値', '{"id": "T-M1-C1-001", "item": "M1-C1", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 1, "title": "比例の式と値", "variables": {"a": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "x0": {"type": "int", "min": -9, "max": 9, "exclude": [0]}}, "constraints": [], "derived": {"ans": "a * x0"}, "body": "y は x に比例し、y = {a}x と表されます。\nx = {x0} のときの y の値を求めなさい。", "answers": {"y": "ans"}, "explanation": "x に {x0} を代入します。\ny = {a} × ({x0}) = {ans}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-C1-002', 'M1-C1-K2', 'numeric', 2, '比例定数を求める', '{"id": "T-M1-C1-002", "item": "M1-C1", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "比例定数を求める", "variables": {"a": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "x0": {"type": "int", "min": 1, "max": 9}}, "constraints": [], "derived": {"y0": "a * x0", "ans": "a"}, "body": "y は x に比例し、x = {x0} のとき y = {y0} です。\n比例定数を求めなさい。", "answers": {"比例定数": "ans"}, "explanation": "比例の式は y = ax と表せます。x = {x0}, y = {y0} を代入すると\n{y0} = a × {x0}\na = {ans}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-C1-003', 'M1-C1-K2', 'numeric', 2, '反比例の式と値', '{"id": "T-M1-C1-003", "item": "M1-C1", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "反比例の式と値", "variables": {"x0": {"type": "int", "min": 1, "max": 12}, "y0": {"type": "int", "min": -9, "max": 9, "exclude": [0]}}, "constraints": [], "derived": {"a": "x0 * y0", "ans": "y0"}, "body": "y は x に反比例し、y = {a}/x と表されます。\nx = {x0} のときの y の値を求めなさい。", "answers": {"y": "ans"}, "explanation": "x に {x0} を代入します。\ny = {a} ÷ {x0} = {ans}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-C1-004', 'M1-C1-K3', 'numeric', 1, '座標と対称な点', '{"id": "T-M1-C1-004", "item": "M1-C1", "item_kind": "knowledge", "item_index": 3, "format": "numeric", "difficulty": 1, "title": "座標と対称な点", "variables": {"x1": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "y1": {"type": "int", "min": -9, "max": 9, "exclude": [0]}}, "constraints": [], "derived": {"nx": "0 - x1", "ny": "0 - y1"}, "body": "点A({x1}, {y1}) と x 軸について対称な点Bの座標を答えなさい。", "answers": {"x座標": "x1", "y座標": "ny"}, "explanation": "x 軸について対称な点は、x 座標がそのままで y 座標の符号が変わります。\nよってBの座標は ({x1}, {ny}) です。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-C1-005', 'M1-C1-K1', 'choice', 1, '関数と変域', '{"id": "T-M1-C1-005", "item": "M1-C1", "item_kind": "knowledge", "item_index": 1, "format": "choice", "difficulty": 1, "title": "関数と変域", "variables": {"q": {"type": "int", "min": 1, "max": 4}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "2つの数量 x, y があり、x の値を決めると y の値がただ1つに決まるとき、y は x の何であるといいますか。", "2": "変数のとりうる値の範囲を何といいますか。", "3": "比例 y = ax で、x の値が2倍、3倍になると y の値はどうなりますか。", "4": "反比例 y = a/x で、x の値が2倍、3倍になると y の値はどうなりますか。"}, "correct_by_case": {"1": "関数", "2": "変域", "3": "2倍、3倍になる", "4": "2分の1、3分の1になる"}, "distractors_by_case": {"1": ["定数", "変域", "係数"], "2": ["関数", "座標", "比例定数"], "3": ["半分、3分の1になる", "変わらない", "2倍、4倍になる"], "4": ["2倍、3倍になる", "変わらない", "4倍、9倍になる"]}, "explanation": "x の値を決めると y の値がただ1つ決まるとき、y は x の関数であるといいます。\n比例では x が2倍になると y も2倍に、反比例では x が2倍になると y は 1/2 倍になります。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-C1-006', 'M1-C1-K4', 'choice', 1, '比例・反比例のグラフ', '{"id": "T-M1-C1-006", "item": "M1-C1", "item_kind": "knowledge", "item_index": 4, "format": "choice", "difficulty": 1, "title": "比例・反比例のグラフ", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "比例 y = ax のグラフはどんな形になりますか。", "2": "反比例 y = a/x のグラフはどんな形になりますか。", "3": "比例 y = ax で a < 0 のとき、グラフはどの向きになりますか。"}, "correct_by_case": {"1": "原点を通る直線", "2": "双曲線", "3": "右下がり"}, "distractors_by_case": {"1": ["原点を通らない直線", "双曲線", "放物線"], "2": ["原点を通る直線", "放物線", "円"], "3": ["右上がり", "水平", "垂直"]}, "explanation": "比例のグラフは原点を通る直線、反比例のグラフは双曲線とよばれる2つの曲線になります。\n比例定数が負のとき、比例のグラフは右下がりの直線になります。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-C1-007', 'M1-C1-T1', 'choice', 2, '変化や対応の特徴', '{"id": "T-M1-C1-007", "item": "M1-C1", "item_kind": "thinking", "item_index": 1, "format": "choice", "difficulty": 2, "title": "変化や対応の特徴", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "表で、x が1増えるごとに y がいつも同じ数ずつ増えている関係はどれですか。", "2": "表で、x と y の積がいつも同じ数になっている関係はどれですか。", "3": "表で、x と y の商 y ÷ x がいつも同じ数になっている関係はどれですか。"}, "correct_by_case": {"1": "比例（一次の関係）", "2": "反比例", "3": "比例"}, "distractors_by_case": {"1": ["反比例", "関数ではない", "常に一定の関係"], "2": ["比例", "関数ではない", "和が一定の関係"], "3": ["反比例", "関数ではない", "差が一定の関係"]}, "explanation": "比例では y ÷ x が一定（比例定数）になり、反比例では x × y が一定（比例定数）になります。\n表・式・グラフを結びつけて特徴を読み取ります。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-C1-008', 'M1-C1-T2', 'numeric', 2, '比例の活用（道のり）', '{"id": "T-M1-C1-008", "item": "M1-C1", "item_kind": "thinking", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "比例の活用（道のり）", "variables": {"a": {"type": "int", "min": 40, "max": 90}, "t": {"type": "int", "min": 3, "max": 30}}, "constraints": [], "derived": {"ans": "a * t"}, "body": "分速 {a}m で歩くとき、x 分間に進む道のりを y m とします。\n{t} 分間に進む道のりを求めなさい。", "answers": {"道のり": "ans"}, "explanation": "道のりは （速さ）×（時間）なので y = {a}x と表せます。\nx = {t} を代入して y = {a} × {t} = {ans}（m）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-D1-001', 'M1-D1-K1', 'numeric', 2, '相対度数', '{"id": "T-M1-D1-001", "item": "M1-D1", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 2, "title": "相対度数", "variables": {"a": {"type": "int", "min": 1, "max": 19}}, "constraints": [], "derived": {"n": "20", "ans": "a * 5"}, "body": "{n}人のクラスで、通学時間が10分未満の人は {a}人でした。\nこの階級の相対度数を百分率（％）で答えなさい。", "answers": {"割合": "ans"}, "explanation": "相対度数は （その階級の度数）÷（度数の合計）で求めます。\n{a} ÷ {n} を計算し、100をかけると {ans}％ です。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-D1-002', 'M1-D1-K1', 'numeric', 1, 'データの範囲', '{"id": "T-M1-D1-002", "item": "M1-D1", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 1, "title": "データの範囲", "variables": {"mn": {"type": "int", "min": 0, "max": 30}, "d": {"type": "int", "min": 1, "max": 40}}, "constraints": [], "derived": {"mx": "mn + d", "ans": "d"}, "body": "あるデータの最大値は {mx}、最小値は {mn} でした。\nこのデータの範囲を求めなさい。", "answers": {"範囲": "ans"}, "explanation": "範囲は （最大値）-（最小値）で求めます。\n{mx} - {mn} = {ans}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-D1-003', 'M1-D1-K2', 'numeric', 1, '累積度数', '{"id": "T-M1-D1-003", "item": "M1-D1", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 1, "title": "累積度数", "variables": {"f1": {"type": "int", "min": 1, "max": 12}, "f2": {"type": "int", "min": 1, "max": 12}, "f3": {"type": "int", "min": 1, "max": 12}}, "constraints": [], "derived": {"ans": "f1 + f2 + f3"}, "body": "度数分布表で、小さいほうから3つの階級の度数が順に {f1}人、{f2}人、{f3}人でした。\n3つ目の階級までの累積度数を求めなさい。", "answers": {"累積度数": "ans"}, "explanation": "累積度数は、その階級までの度数をすべてたした値です。\n{f1} + {f2} + {f3} = {ans}（人）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-D1-004', 'M1-D1-K1', 'choice', 1, 'データの用語', '{"id": "T-M1-D1-004", "item": "M1-D1", "item_kind": "knowledge", "item_index": 1, "format": "choice", "difficulty": 1, "title": "データの用語", "variables": {"q": {"type": "int", "min": 1, "max": 4}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "度数分布のようすを長方形の柱で表したグラフを何といいますか。", "2": "各階級の度数を、度数の合計でわった値を何といいますか。", "3": "階級の真ん中の値を何といいますか。", "4": "データの最大値と最小値の差を何といいますか。"}, "correct_by_case": {"1": "ヒストグラム", "2": "相対度数", "3": "階級値", "4": "範囲"}, "distractors_by_case": {"1": ["折れ線グラフ", "円グラフ", "箱ひげ図"], "2": ["累積度数", "範囲", "階級値"], "3": ["中央値", "相対度数", "範囲"], "4": ["階級", "中央値", "度数"]}, "explanation": "ヒストグラムは分布のようすを柱で表したグラフです。\n相対度数は全体に対する割合、階級値は階級の真ん中の値、範囲は最大値と最小値の差です。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-D1-005', 'M1-D1-T1', 'choice', 2, '分布の読み取り', '{"id": "T-M1-D1-005", "item": "M1-D1", "item_kind": "thinking", "item_index": 1, "format": "choice", "difficulty": 2, "title": "分布の読み取り", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "人数のちがう2つのクラスの分布を比べるとき、度数と相対度数のどちらを使うのが適切ですか。", "2": "ヒストグラムから読み取れることとして正しいものはどれですか。", "3": "「平均値だけで判断してはいけない」といわれるのはなぜですか。"}, "correct_by_case": {"1": "相対度数", "2": "どの階級に多く集まっているか", "3": "極端な値の影響を受けやすいから"}, "distractors_by_case": {"1": ["度数", "階級値", "累積度数"], "2": ["1人ひとりの正確な値", "データの合計金額", "調査した日付"], "3": ["計算が難しいから", "必ず整数にならないから", "度数が分からないから"]}, "explanation": "全体の人数がちがう集団を比べるときは、割合である相対度数を使います。\nヒストグラムからは分布の中心や散らばりの傾向が読み取れます。平均値は極端な値の影響を受けるため、\n分布全体を見て批判的に判断することが大切です。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-D2-001', 'M1-D2-K1', 'numeric', 2, '多数回の試行と確率', '{"id": "T-M1-D2-001", "item": "M1-D2", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 2, "title": "多数回の試行と確率", "variables": {"m": {"type": "int", "min": 20, "max": 80}}, "constraints": [], "derived": {"n": "200", "a": "2 * m", "ans": "m"}, "body": "あるコインを {n}回投げたところ、表が {a}回出ました。\n表が出る相対度数を百分率（％）で答えなさい。", "answers": {"割合": "ans"}, "explanation": "相対度数は （表が出た回数）÷（投げた回数）で求めます。\n{a} ÷ {n} を計算し、100をかけると {ans}％ です。\n投げる回数を増やすほど、この値は確率に近づいていきます。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-D2-002', 'M1-D2-K1', 'choice', 1, '確率の意味', '{"id": "T-M1-D2-002", "item": "M1-D2", "item_kind": "knowledge", "item_index": 1, "format": "choice", "difficulty": 1, "title": "確率の意味", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "多数回の試行で得られる相対度数は、試行回数を増やすとどうなりますか。", "2": "「表が出る確率が0.5」であるコインを10回投げたとき、必ず起こることはどれですか。", "3": "確率がとりうる値の範囲はどれですか。"}, "correct_by_case": {"1": "一定の値に近づく", "2": "必ず5回表が出るとは限らない", "3": "0以上1以下"}, "distractors_by_case": {"1": ["どんどん大きくなる", "0に近づく", "ばらばらのまま"], "2": ["必ず5回表が出る", "必ず表が先に出る", "必ず裏が5回出る"], "3": ["0以上100以下", "1以上10以下", "決まっていない"]}, "explanation": "多数回の試行をくり返すと相対度数は一定の値に近づき、その値を確率と考えます。\n確率は0以上1以下の値で、個々の結果を確実に予言するものではありません。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-D2-003', 'M1-D2-T1', 'choice', 2, '起こりやすさの読み取り', '{"id": "T-M1-D2-003", "item": "M1-D2", "item_kind": "thinking", "item_index": 1, "format": "choice", "difficulty": 2, "title": "起こりやすさの読み取り", "variables": {"q": {"type": "int", "min": 1, "max": 2}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "ペットボトルのふたを100回投げて表が62回出ました。このデータから言えることはどれですか。", "2": "同じ実験を10回だけ行った結果と1000回行った結果では、どちらが確率のよい見積もりになりますか。"}, "correct_by_case": {"1": "表が出やすい傾向がある", "2": "1000回行った結果"}, "distractors_by_case": {"1": ["必ず表が出る", "表と裏は同じ出やすさである", "何も言えない"], "2": ["10回行った結果", "どちらも同じ", "回数とは関係ない"]}, "explanation": "多数回の試行の結果から相対度数を求めると、起こりやすさの傾向を読み取れます。\n試行回数が多いほど、相対度数は確率に近い値になります。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A1-001', 'M2-A1-K1', 'numeric', 1, '整式の加法', '{"id": "T-M2-A1-001", "item": "M2-A1", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 1, "title": "整式の加法", "variables": {"a": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "b": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "c": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "d": {"type": "int", "min": -9, "max": 9, "exclude": [0]}}, "constraints": [], "derived": {"kx": "a + c", "ky": "b + d"}, "body": "次の式を計算した結果について、x の係数と y の係数を答えなさい。\n({a}x + ({b})y) + ({c}x + ({d})y)", "answers": {"xの係数": "kx", "yの係数": "ky"}, "explanation": "同類項どうしをまとめます。\nxの項: {a}x + {c}x = {kx}x\nyの項: ({b})y + ({d})y = {ky}y", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A1-002', 'M2-A1-K1', 'numeric', 2, '整式の減法', '{"id": "T-M2-A1-002", "item": "M2-A1", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 2, "title": "整式の減法", "variables": {"a": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "b": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "c": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "d": {"type": "int", "min": -9, "max": 9, "exclude": [0]}}, "constraints": [], "derived": {"kx": "a - c", "ky": "b - d"}, "body": "次の式を計算した結果について、x の係数と y の係数を答えなさい。\n({a}x + ({b})y) - ({c}x + ({d})y)", "answers": {"xの係数": "kx", "yの係数": "ky"}, "explanation": "かっこの前が - のときは、かっこの中の各項の符号を変えてから同類項をまとめます。\nxの項: {a}x - {c}x = {kx}x\nyの項: ({b})y - ({d})y = {ky}y", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A1-003', 'M2-A1-K1', 'numeric', 1, '単項式の乗法', '{"id": "T-M2-A1-003", "item": "M2-A1", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 1, "title": "単項式の乗法", "variables": {"a": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "b": {"type": "int", "min": -9, "max": 9, "exclude": [0]}}, "constraints": [], "derived": {"ans": "a * b"}, "body": "次の計算をした結果について、xy の係数を答えなさい。\n{a}x × ({b})y", "answers": {"xyの係数": "ans"}, "explanation": "係数どうし、文字どうしをかけます。\n{a} × ({b}) = {ans}、x × y = xy なので、答えは {ans}xy です。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A1-004', 'M2-A1-K1', 'numeric', 2, '単項式の除法', '{"id": "T-M2-A1-004", "item": "M2-A1", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 2, "title": "単項式の除法", "variables": {"q": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "b": {"type": "int", "min": -9, "max": 9, "exclude": [0]}}, "constraints": [], "derived": {"a": "q * b", "ans": "q"}, "body": "次の計算をした結果について、x の係数を答えなさい。\n{a}x² ÷ ({b})x", "answers": {"xの係数": "ans"}, "explanation": "係数どうし、文字どうしでわります。\n{a} ÷ ({b}) = {ans}、x² ÷ x = x なので、答えは {ans}x です。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A1-005', 'M2-A1-K2', 'numeric', 2, '2つの文字をふくむ式の値', '{"id": "T-M2-A1-005", "item": "M2-A1", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "2つの文字をふくむ式の値", "variables": {"a": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "b": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "x0": {"type": "int", "min": -6, "max": 6, "exclude": [0]}, "y0": {"type": "int", "min": -6, "max": 6, "exclude": [0]}}, "constraints": [], "derived": {"ax": "a * x0", "by": "b * y0", "ans": "a * x0 + b * y0"}, "body": "x = {x0}, y = {y0} のとき、次の式の値を求めなさい。\n{a}x + ({b})y", "answers": {"値": "ans"}, "explanation": "x と y にそれぞれ代入します。\n{a} × ({x0}) = {ax}、({b}) × ({y0}) = {by}\n{ax} + ({by}) = {ans}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A1-006', 'M2-A1-K3', 'choice', 2, '文字式による説明', '{"id": "T-M2-A1-006", "item": "M2-A1", "item_kind": "knowledge", "item_index": 3, "format": "choice", "difficulty": 2, "title": "文字式による説明", "variables": {"q": {"type": "int", "min": 1, "max": 4}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "m, n を整数とするとき、偶数を表す式はどれですか。", "2": "m, n を整数とするとき、奇数を表す式はどれですか。", "3": "連続する2つの整数を表す式の組はどれですか。", "4": "十の位が a、一の位が b である2けたの整数を表す式はどれですか。"}, "correct_by_case": {"1": "2n", "2": "2n + 1", "3": "n, n + 1", "4": "10a + b"}, "distractors_by_case": {"1": ["2n + 1", "n + 2", "n²"], "2": ["2n", "n + 1", "3n"], "3": ["n, n + 2", "2n, 2n + 1", "n, 2n"], "4": ["ab", "a + b", "a + 10b"]}, "explanation": "文字を使うと、あてはまる数すべてに共通する性質を説明できます。\nn を整数とすると 2n は偶数、2n + 1 は奇数を表します。\n2けたの整数は、位取りを考えて 10a + b と表します。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A1-007', 'M2-A1-K4', 'choice', 2, '等式の変形', '{"id": "T-M2-A1-007", "item": "M2-A1", "item_kind": "knowledge", "item_index": 4, "format": "choice", "difficulty": 2, "title": "等式の変形", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "2x + y = 5 を y について解くとどうなりますか。", "2": "S = ab を b について解くとどうなりますか。", "3": "ℓ = 2(a + b) を a について解くとどうなりますか。"}, "correct_by_case": {"1": "y = -2x + 5", "2": "b = S/a", "3": "a = ℓ/2 - b"}, "distractors_by_case": {"1": ["y = 2x + 5", "y = 5 - x", "y = 2x - 5"], "2": ["b = aS", "b = S - a", "b = a/S"], "3": ["a = ℓ - 2b", "a = 2ℓ - b", "a = ℓ/2 + b"]}, "explanation": "等式を「○について解く」とは、その文字だけが左辺に残る形に変形することです。\n等式の性質を使い、他の項を移項したり両辺を同じ数でわったりします。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A1-008', 'M2-A1-T1', 'choice', 1, '式の計算の方法', '{"id": "T-M2-A1-008", "item": "M2-A1", "item_kind": "thinking", "item_index": 1, "format": "choice", "difficulty": 1, "title": "式の計算の方法", "variables": {"q": {"type": "int", "min": 1, "max": 2}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "3a + 2b と 2a - 5b をたすとき、なぜ a どうし、b どうしをまとめるのですか。", "2": "単項式 6a²b ÷ 2a の計算で、係数と文字を別々に処理してよいのはなぜですか。"}, "correct_by_case": {"1": "同類項どうしは分配法則でまとめられるから", "2": "乗法・除法では順序を入れかえてよいから"}, "distractors_by_case": {"1": ["文字の順番が決まっているから", "係数が違うから", "答えを短くする決まりだから"], "2": ["係数のほうが大切だから", "文字は消えるから", "答えが整数になるから"]}, "explanation": "式の計算は、数の計算で成り立つ交換法則・結合法則・分配法則がそのまま使えることを\n根拠にしています。同類項は分配法則により1つの項にまとめられます。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A1-009', 'M2-A1-T2', 'numeric', 2, '文字式の活用（連続する整数）', '{"id": "T-M2-A1-009", "item": "M2-A1", "item_kind": "thinking", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "文字式の活用（連続する整数）", "variables": {"n": {"type": "int", "min": 2, "max": 40}}, "constraints": [], "derived": {"n1": "n + 1", "n2": "n + 2", "ans": "3 * n + 3"}, "body": "連続する3つの整数 {n}, {n1}, {n2} の和を求めなさい。", "answers": {"和": "ans"}, "explanation": "連続する3つの整数は n, n + 1, n + 2 と表せます。\n和は n + (n + 1) + (n + 2) = 3n + 3 = 3(n + 1) となり、\n真ん中の数の3倍になります。ここでは 3 × {n1} = {ans} です。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A2-002', 'M2-A2-K3', 'numeric', 2, '連立方程式（代入法）', '{"id": "T-M2-A2-002", "item": "M2-A2", "item_kind": "knowledge", "item_index": 3, "format": "numeric", "difficulty": 2, "title": "連立方程式（代入法）", "variables": {"m": {"type": "int", "min": -4, "max": 4, "exclude": [0]}, "n": {"type": "int", "min": -9, "max": 9}, "x0": {"type": "int", "min": -6, "max": 6}, "a": {"type": "int", "min": 1, "max": 5}, "b": {"type": "int", "min": 1, "max": 5}}, "constraints": [], "derived": {"y0": "m * x0 + n", "c": "a * x0 + b * (m * x0 + n)"}, "body": "次の連立方程式を解きなさい。\ny = {m}x + ({n})\n{a}x + {b}y = {c}", "answers": {"x": "x0", "y": "y0"}, "explanation": "1つ目の式を2つ目の式に代入します。\n{a}x + {b}({m}x + ({n})) = {c}\nこれを解いて x = {x0}\n1つ目の式に代入して y = {y0}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A2-003', 'M2-A2-K1', 'numeric', 1, '二元一次方程式の解', '{"id": "T-M2-A2-003", "item": "M2-A2", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 1, "title": "二元一次方程式の解", "variables": {"a": {"type": "int", "min": 1, "max": 6}, "b": {"type": "int", "min": 1, "max": 6}, "x0": {"type": "int", "min": -6, "max": 6}, "y0": {"type": "int", "min": -6, "max": 6}}, "constraints": [], "derived": {"c": "a * x0 + b * y0", "ax": "a * x0", "rest": "b * y0"}, "body": "二元一次方程式 {a}x + {b}y = {c} について、\nx = {x0} のときの y の値を求めなさい。", "answers": {"y": "y0"}, "explanation": "x に {x0} を代入します。\n{a} × ({x0}) + {b}y = {c}\n{ax} + {b}y = {c}\n{b}y = {rest}\ny = {y0}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A2-004', 'M2-A2-K2', 'choice', 1, '連立方程式と解の意味', '{"id": "T-M2-A2-004", "item": "M2-A2", "item_kind": "knowledge", "item_index": 2, "format": "choice", "difficulty": 1, "title": "連立方程式と解の意味", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "連立方程式の解とはどんな値の組ですか。", "2": "二元一次方程式 x + y = 5 の解は何組ありますか。", "3": "連立方程式を解くときの基本の考え方はどれですか。"}, "correct_by_case": {"1": "どちらの方程式も成り立たせる x, y の組", "2": "無数にある", "3": "文字を1つ消去して一元一次方程式にする"}, "distractors_by_case": {"1": ["1つ目の方程式だけを成り立たせる組", "どちらか一方を成り立たせる組", "式に出てくる数の組"], "2": ["1組だけ", "2組", "解はない"], "3": ["両方の式をたすだけ", "x と y を別々に推測する", "グラフをかかないと解けない"]}, "explanation": "二元一次方程式1つだけでは解が無数にありますが、2つ組み合わせると\nふつう解の組はただ1つに決まります。加減法・代入法はどちらも\n文字を1つ消去して一元一次方程式に帰着させる方法です。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A2-005', 'M2-A2-T2', 'numeric', 2, '連立方程式の活用（代金）', '{"id": "T-M2-A2-005", "item": "M2-A2", "item_kind": "thinking", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "連立方程式の活用（代金）", "variables": {"a": {"type": "int", "min": 80, "max": 200}, "b": {"type": "int", "min": 80, "max": 200}, "x0": {"type": "int", "min": 2, "max": 10}, "y0": {"type": "int", "min": 2, "max": 10}}, "constraints": ["a != b"], "derived": {"n": "x0 + y0", "total": "a * x0 + b * y0"}, "body": "1個 {a}円のパンと1個 {b}円のジュースを合わせて {n}個買ったところ、\n代金の合計は {total}円でした。パンとジュースをそれぞれ何個買いましたか。", "answers": {"パンの個数": "x0", "ジュースの個数": "y0"}, "explanation": "パンを x 個、ジュースを y 個として連立方程式をつくります。\nx + y = {n}\n{a}x + {b}y = {total}\nこれを解いて x = {x0}, y = {y0}（個）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A2-006', 'M2-A2-T1', 'choice', 2, '解き方の選択', '{"id": "T-M2-A2-006", "item": "M2-A2", "item_kind": "thinking", "item_index": 1, "format": "choice", "difficulty": 2, "title": "解き方の選択", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "y = 2x - 1 と 3x + y = 9 を解くとき、能率のよい方法はどれですか。", "2": "2x + 3y = 7 と 2x - y = 3 を解くとき、能率のよい方法はどれですか。", "3": "加減法で式をたしたりひいたりしてよいのはなぜですか。"}, "correct_by_case": {"1": "代入法", "2": "加減法（x を消去）", "3": "等式の両辺に同じ量を加減しているから"}, "distractors_by_case": {"1": ["加減法だけしか使えない", "グラフをかく", "順に代入して試す"], "2": ["代入法しか使えない", "両辺をかけ算する", "y を先に推測する"], "3": ["式は自由に組み合わせてよいから", "係数がそろっているから", "解が整数だから"]}, "explanation": "一方の式が「y = …」の形なら代入法、同じ文字の係数がそろっていれば加減法が能率的です。\nどちらも等式の性質にもとづいており、文字を1つ消去する点は同じです。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A2-007', 'M2-A2-K3', 'numeric', 1, '連立方程式（和と差）', '{"id": "T-M2-A2-007", "item": "M2-A2", "item_kind": "knowledge", "item_index": 3, "format": "numeric", "difficulty": 1, "title": "連立方程式（和と差）", "variables": {"x0": {"type": "int", "min": -9, "max": 9}, "y0": {"type": "int", "min": -9, "max": 9}}, "constraints": [], "derived": {"s": "x0 + y0", "d": "x0 - y0"}, "body": "次の連立方程式を解きなさい。\nx + y = {s}\nx - y = {d}", "answers": {"x": "x0", "y": "y0"}, "explanation": "2つの式をたすと y が消えます。\n2x = {s} + ({d})\nx = {x0}\n1つ目の式に代入して y = {y0}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-B1-001', 'M2-B1-K1', 'numeric', 1, '2直線が交わってできる角', '{"id": "T-M2-B1-001", "item": "M2-B1", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 1, "title": "2直線が交わってできる角", "variables": {"d": {"type": "int", "min": 20, "max": 160}}, "constraints": [], "derived": {"ans": "180 - d"}, "body": "2つの直線が交わってできる4つの角のうち、1つの角の大きさは {d}° です。\nこの角ととなり合う角の大きさを求めなさい。", "answers": {"角度": "ans"}, "explanation": "となり合う2つの角は一直線をつくるので、和は180°になります。\n180 - {d} = {ans}（°）\n（なお、向かい合う角＝対頂角は {d}° で等しくなります。）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-B1-002', 'M2-B1-K2', 'numeric', 1, '多角形の内角の和', '{"id": "T-M2-B1-002", "item": "M2-B1", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 1, "title": "多角形の内角の和", "variables": {"n": {"type": "int", "min": 3, "max": 15}}, "constraints": [], "derived": {"ans": "180 * (n - 2)"}, "body": "{n}角形の内角の和を求めなさい。", "answers": {"内角の和": "ans"}, "explanation": "n角形は、1つの頂点から対角線をひくと (n - 2) 個の三角形に分けられます。\n内角の和は 180 × ({n} - 2) = {ans}（°）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-B1-003', 'M2-B1-K2', 'numeric', 2, '正多角形の1つの内角', '{"id": "T-M2-B1-003", "item": "M2-B1", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "正多角形の1つの内角", "variables": {"n": {"type": "int", "min": 3, "max": 12, "exclude": [7, 11]}}, "constraints": [], "derived": {"total": "180 * (n - 2)", "ans": "180 * (n - 2) / n"}, "body": "正{n}角形の1つの内角の大きさを求めなさい。", "answers": {"内角": "ans"}, "explanation": "正{n}角形の内角の和は 180 × ({n} - 2) = {total}（°）です。\nすべての内角が等しいので、{total} ÷ {n} = {ans}（°）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-B1-004', 'M2-B1-K2', 'numeric', 2, '正多角形の1つの外角', '{"id": "T-M2-B1-004", "item": "M2-B1", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "正多角形の1つの外角", "variables": {"n": {"type": "int", "min": 3, "max": 12, "exclude": [7, 11]}}, "constraints": [], "derived": {"ans": "360 / n"}, "body": "正{n}角形の1つの外角の大きさを求めなさい。", "answers": {"外角": "ans"}, "explanation": "多角形の外角の和は、何角形でも360°です。\n正{n}角形はすべての外角が等しいので、360 ÷ {n} = {ans}（°）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-B1-005', 'M2-B1-K1', 'choice', 1, '平行線と角', '{"id": "T-M2-B1-005", "item": "M2-B1", "item_kind": "knowledge", "item_index": 1, "format": "choice", "difficulty": 1, "title": "平行線と角", "variables": {"q": {"type": "int", "min": 1, "max": 4}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "2直線が平行のとき、同位角どうしの関係はどうなりますか。", "2": "2直線が平行のとき、錯角どうしの関係はどうなりますか。", "3": "2直線に1つの直線が交わり、錯角が等しいとき、2直線はどうなりますか。", "4": "対頂角どうしの関係はどうなりますか。"}, "correct_by_case": {"1": "等しい", "2": "等しい", "3": "平行である", "4": "いつも等しい"}, "distractors_by_case": {"1": ["和が180°になる", "差が90°になる", "関係はない"], "2": ["和が180°になる", "差が90°になる", "関係はない"], "3": ["垂直である", "必ず交わる", "何も言えない"], "4": ["平行のときだけ等しい", "和が180°になる", "関係はない"]}, "explanation": "対頂角はいつも等しくなります。2直線が平行のときは同位角・錯角がそれぞれ等しく、\n逆に同位角または錯角が等しければ、2直線は平行であるといえます。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-B1-006', 'M2-B1-T1', 'choice', 2, '角の性質を使った説明', '{"id": "T-M2-B1-006", "item": "M2-B1", "item_kind": "thinking", "item_index": 1, "format": "choice", "difficulty": 2, "title": "角の性質を使った説明", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "三角形の内角の和が180°であることは、どの性質を使って説明できますか。", "2": "三角形の外角は、それととなり合わない2つの内角の和とどんな関係ですか。", "3": "多角形の外角の和が360°になるのは何角形のときですか。"}, "correct_by_case": {"1": "平行線の錯角・同位角が等しいこと", "2": "等しい", "3": "どの多角形でも360°"}, "distractors_by_case": {"1": ["三角形の合同条件", "円周角の定理", "三平方の定理"], "2": ["和が180°になる", "半分になる", "関係はない"], "3": ["三角形のときだけ", "正多角形のときだけ", "四角形以上のとき"]}, "explanation": "1つの頂点を通り対辺に平行な直線をひくと、錯角・同位角が等しいことから\n三角形の内角の和が180°であることを説明できます。\n外角の和は、どの多角形でも360°になります。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-B1-007', 'M2-B1-K1', 'numeric', 1, '三角形の内角', '{"id": "T-M2-B1-007", "item": "M2-B1", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 1, "title": "三角形の内角", "variables": {"a": {"type": "int", "min": 20, "max": 120}, "b": {"type": "int", "min": 20, "max": 120}}, "constraints": ["180 - a - b > 0"], "derived": {"ans": "180 - a - b"}, "body": "三角形の2つの内角の大きさが {a}° と {b}° です。\n残りの内角の大きさを求めなさい。", "answers": {"角度": "ans"}, "explanation": "三角形の内角の和は180°です。\n180 - {a} - {b} = {ans}（°）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-B2-002', 'M2-B2-K2', 'choice', 1, '証明の用語', '{"id": "T-M2-B2-002", "item": "M2-B2", "item_kind": "knowledge", "item_index": 2, "format": "choice", "difficulty": 1, "title": "証明の用語", "variables": {"q": {"type": "int", "min": 1, "max": 5}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "証明で、「〜ならば」の部分にあたるものを何といいますか。", "2": "証明で、「〜である」と示したい部分を何といいますか。", "3": "言葉の意味をはっきり述べたものを何といいますか。", "4": "「AならばB」に対して「BならばA」を何といいますか。", "5": "あることがらが成り立たない例を1つ示すことを何といいますか。"}, "correct_by_case": {"1": "仮定", "2": "結論", "3": "定義", "4": "逆", "5": "反例をあげる"}, "distractors_by_case": {"1": ["結論", "定義", "定理"], "2": ["仮定", "定義", "逆"], "3": ["定理", "仮定", "証明"], "4": ["対偶", "仮定", "定理"], "5": ["証明する", "定義する", "仮定する"]}, "explanation": "証明は仮定から出発し、すでに正しいと分かっていることを根拠にして結論を導きます。\nあることがらが成り立たないことを示すには、反例を1つあげれば十分です。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-B2-003', 'M2-B2-T1', 'numeric', 1, '平行四辺形の角', '{"id": "T-M2-B2-003", "item": "M2-B2", "item_kind": "thinking", "item_index": 1, "format": "numeric", "difficulty": 1, "title": "平行四辺形の角", "variables": {"a": {"type": "int", "min": 30, "max": 150}}, "constraints": [], "derived": {"ans": "180 - a"}, "body": "平行四辺形ABCDで、∠A = {a}° です。∠B の大きさを求めなさい。", "answers": {"角度": "ans"}, "explanation": "平行四辺形では、となり合う角の和が180°になります（AD // BC より錯角・同側内角の性質）。\n180 - {a} = {ans}（°）\n（なお、向かい合う角は等しいので ∠C = {a}° です。）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-B2-004', 'M2-B2-T1', 'choice', 2, '証明の読み取り', '{"id": "T-M2-B2-004", "item": "M2-B2", "item_kind": "thinking", "item_index": 1, "format": "choice", "difficulty": 2, "title": "証明の読み取り", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "△ABCと△DEFで、AB=DE、∠B=∠E、BC=EF が分かっています。使える合同条件はどれですか。", "2": "△ABCと△DEFで、∠B=∠E、BC=EF、∠C=∠F が分かっています。使える合同条件はどれですか。", "3": "「3組の角がそれぞれ等しい」が合同条件にならないのはなぜですか。"}, "correct_by_case": {"1": "2組の辺とその間の角がそれぞれ等しい", "2": "1組の辺とその両端の角がそれぞれ等しい", "3": "形は同じでも大きさが違う場合があるから"}, "distractors_by_case": {"1": ["3組の辺がそれぞれ等しい", "1組の辺とその両端の角がそれぞれ等しい", "3組の角がそれぞれ等しい"], "2": ["3組の辺がそれぞれ等しい", "2組の辺とその間の角がそれぞれ等しい", "3組の角がそれぞれ等しい"], "3": ["角は測りにくいから", "辺の情報がないと計算できないから", "3つも条件がいらないから"]}, "explanation": "合同条件は「3組の辺」「2組の辺とその間の角」「1組の辺とその両端の角」の3つです。\n角だけがすべて等しい図形は相似ですが、大きさが異なる場合があるため合同とは限りません。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-B2-005', 'M2-B2-T2', 'numeric', 2, '平行四辺形の辺の長さ', '{"id": "T-M2-B2-005", "item": "M2-B2", "item_kind": "thinking", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "平行四辺形の辺の長さ", "variables": {"a": {"type": "int", "min": 3, "max": 20}, "b": {"type": "int", "min": 3, "max": 20}}, "constraints": [], "derived": {"ans": "2 * (a + b)"}, "body": "平行四辺形ABCDで、AB = {a}cm、BC = {b}cm です。\nこの平行四辺形の周の長さを求めなさい。", "answers": {"周の長さ": "ans"}, "explanation": "平行四辺形では、向かい合う辺の長さは等しくなります。\nAB = CD = {a}cm、BC = AD = {b}cm なので\n周の長さは 2 × ({a} + {b}) = {ans}（cm）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-B2-006', 'M2-B2-K1', 'numeric', 1, '合同な図形の対応', '{"id": "T-M2-B2-006", "item": "M2-B2", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 1, "title": "合同な図形の対応", "variables": {"a": {"type": "int", "min": 3, "max": 20}, "b": {"type": "int", "min": 3, "max": 20}}, "constraints": [], "derived": {"ans": "a"}, "body": "△ABC ≡ △DEF で、AB = {a}cm、BC = {b}cm です。\nDE の長さを求めなさい。", "answers": {"長さ": "ans"}, "explanation": "合同な図形では、対応する辺の長さは等しくなります。\n△ABC ≡ △DEF なので、AB と DE が対応します。\nDE = AB = {ans}（cm）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-C1-002', 'M2-C1-K1', 'numeric', 1, '一次関数の式と値', '{"id": "T-M2-C1-002", "item": "M2-C1", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 1, "title": "一次関数の式と値", "variables": {"a": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "b": {"type": "int", "min": -9, "max": 9}, "x0": {"type": "int", "min": -9, "max": 9}}, "constraints": [], "derived": {"ax": "a * x0", "ans": "a * x0 + b"}, "body": "一次関数 y = {a}x + ({b}) について、x = {x0} のときの y の値を求めなさい。", "answers": {"y": "ans"}, "explanation": "x に {x0} を代入します。\n{a} × ({x0}) = {ax}\ny = {ax} + ({b}) = {ans}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-C1-003', 'M2-C1-K1', 'numeric', 2, '2点から一次関数の式を求める', '{"id": "T-M2-C1-003", "item": "M2-C1", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 2, "title": "2点から一次関数の式を求める", "variables": {"m": {"type": "int", "min": -5, "max": 5, "exclude": [0]}, "n": {"type": "int", "min": -9, "max": 9}, "x1": {"type": "int", "min": -5, "max": 5}, "dx": {"type": "int", "min": 1, "max": 6}}, "constraints": [], "derived": {"x2": "x1 + dx", "y1": "m * x1 + n", "y2": "m * (x1 + dx) + n", "dy": "m * dx"}, "body": "一次関数のグラフが2点 ({x1}, {y1}), ({x2}, {y2}) を通ります。\nこの一次関数の傾きと切片を求めなさい。", "answers": {"傾き": "m", "切片": "n"}, "explanation": "傾きは （yの増加量）÷（xの増加量）で求めます。\n({y2} - ({y1})) ÷ ({x2} - ({x1})) = {dy} ÷ {dx} = {m}\ny = {m}x + b に ({x1}, {y1}) を代入して b = {n}", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-C1-004', 'M2-C1-K3', 'numeric', 2, '二元一次方程式を関数とみる', '{"id": "T-M2-C1-004", "item": "M2-C1", "item_kind": "knowledge", "item_index": 3, "format": "numeric", "difficulty": 2, "title": "二元一次方程式を関数とみる", "variables": {"m": {"type": "int", "min": -5, "max": 5, "exclude": [0]}, "n": {"type": "int", "min": -9, "max": 9}, "k": {"type": "int", "min": 1, "max": 4}}, "constraints": [], "derived": {"A": "k * m", "B": "0 - k", "C": "0 - k * n"}, "body": "二元一次方程式 {A}x + ({B})y = {C} を y について解き、\n傾きと切片を答えなさい。", "answers": {"傾き": "m", "切片": "n"}, "explanation": "y の項だけを左辺に残すように変形します。\n({B})y = -({A})x + ({C})\n両辺を {B} でわると y = {m}x + ({n})\nよって傾きは {m}、切片は {n} です。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-C1-005', 'M2-C1-K2', 'numeric', 2, '一次関数とみられる事象', '{"id": "T-M2-C1-005", "item": "M2-C1", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "一次関数とみられる事象", "variables": {"n0": {"type": "int", "min": 5, "max": 40}, "m": {"type": "int", "min": 2, "max": 12}, "t": {"type": "int", "min": 1, "max": 20}}, "constraints": [], "derived": {"mt": "m * t", "ans": "n0 + m * t"}, "body": "水そうに水が {n0}L 入っています。ここへ毎分 {m}L ずつ水を入れます。\n{t} 分後の水の量は何 L ですか。", "answers": {"水の量": "ans"}, "explanation": "x 分後の水の量 y L は y = {m}x + {n0} と表せます（一次関数）。\nx = {t} を代入して {m} × {t} = {mt}\ny = {mt} + {n0} = {ans}（L）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-C1-006', 'M2-C1-T1', 'choice', 1, '表・式・グラフの関係', '{"id": "T-M2-C1-006", "item": "M2-C1", "item_kind": "thinking", "item_index": 1, "format": "choice", "difficulty": 1, "title": "表・式・グラフの関係", "variables": {"q": {"type": "int", "min": 1, "max": 4}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "一次関数 y = ax + b で、a は グラフの何を表しますか。", "2": "一次関数 y = ax + b で、b は グラフの何を表しますか。", "3": "一次関数で、変化の割合はグラフの何と一致しますか。", "4": "一次関数 y = ax + b で a < 0 のとき、グラフはどうなりますか。"}, "correct_by_case": {"1": "傾き", "2": "切片（y軸との交点のy座標）", "3": "傾き", "4": "右下がりの直線"}, "distractors_by_case": {"1": ["切片", "x の変域", "y の最大値"], "2": ["傾き", "x軸との交点", "変化の割合"], "3": ["切片", "原点からの距離", "x の値"], "4": ["右上がりの直線", "曲線", "水平な直線"]}, "explanation": "一次関数 y = ax + b のグラフは直線で、a が傾き（＝変化の割合）、b が切片です。\na > 0 なら右上がり、a < 0 なら右下がりの直線になります。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-C1-007', 'M2-C1-T2', 'numeric', 2, '2直線の交点', '{"id": "T-M2-C1-007", "item": "M2-C1", "item_kind": "thinking", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "2直線の交点", "variables": {"m1": {"type": "int", "min": -5, "max": 5, "exclude": [0]}, "m2": {"type": "int", "min": -5, "max": 5, "exclude": [0]}, "x0": {"type": "int", "min": -6, "max": 6}, "y0": {"type": "int", "min": -9, "max": 9}}, "constraints": ["m1 != m2"], "derived": {"n1": "y0 - m1 * x0", "n2": "y0 - m2 * x0"}, "body": "2つの直線 y = {m1}x + ({n1}) と y = {m2}x + ({n2}) の交点の座標を求めなさい。", "answers": {"x座標": "x0", "y座標": "y0"}, "explanation": "交点では2つの式の y が等しくなります。\n{m1}x + ({n1}) = {m2}x + ({n2})\nこれを解いて x = {x0}\nどちらかの式に代入して y = {y0}\nよって交点は ({x0}, {y0}) です。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-C1-008', 'M2-C1-K1', 'choice', 1, '一次関数の意味', '{"id": "T-M2-C1-008", "item": "M2-C1", "item_kind": "knowledge", "item_index": 1, "format": "choice", "difficulty": 1, "title": "一次関数の意味", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "y が x の一次関数であるといえるのはどの式ですか。", "2": "一次関数で、x が1増えると y はどうなりますか。", "3": "比例 y = ax は一次関数といえますか。"}, "correct_by_case": {"1": "y = 3x - 2", "2": "傾きの分だけ増える（減る）", "3": "切片が0の一次関数といえる"}, "distractors_by_case": {"1": ["y = 5/x", "y = x²", "y = 2"], "2": ["必ず1増える", "2倍になる", "変わらない"], "3": ["一次関数ではない", "反比例の一種である", "定数関数である"]}, "explanation": "y が x の一次式で表されるとき、y は x の一次関数です。\n比例 y = ax は、切片が0である特別な一次関数とみることができます。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-D1-001', 'M2-D1-K1', 'numeric', 1, '四分位範囲', '{"id": "T-M2-D1-001", "item": "M2-D1", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 1, "title": "四分位範囲", "variables": {"q1": {"type": "int", "min": 1, "max": 50}, "d": {"type": "int", "min": 1, "max": 40}}, "constraints": [], "derived": {"q3": "q1 + d", "ans": "d"}, "body": "あるデータの第1四分位数は {q1}、第3四分位数は {q3} です。\n四分位範囲を求めなさい。", "answers": {"四分位範囲": "ans"}, "explanation": "四分位範囲は （第3四分位数）-（第1四分位数）で求めます。\n{q3} - {q1} = {ans}\n四分位範囲は、中央付近の半分のデータが散らばる幅を表します。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-D1-002', 'M2-D1-K1', 'numeric', 1, '中央値', '{"id": "T-M2-D1-002", "item": "M2-D1", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 1, "title": "中央値", "variables": {"b": {"type": "int", "min": 1, "max": 20}, "d1": {"type": "int", "min": 1, "max": 9}, "d2": {"type": "int", "min": 1, "max": 9}, "d3": {"type": "int", "min": 1, "max": 9}, "d4": {"type": "int", "min": 1, "max": 9}}, "constraints": [], "derived": {"v2": "b + d1", "v3": "b + d1 + d2", "v4": "b + d1 + d2 + d3", "v5": "b + d1 + d2 + d3 + d4", "ans": "b + d1 + d2"}, "body": "次の5個のデータについて、中央値を求めなさい。\n{b}, {v2}, {v3}, {v4}, {v5}", "answers": {"中央値": "ans"}, "explanation": "中央値は、データを小さい順に並べたときのまん中の値です。\n5個のデータなので、小さいほうから3番目の {ans} が中央値になります。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-D1-003', 'M2-D1-K2', 'choice', 1, '箱ひげ図の読み取り', '{"id": "T-M2-D1-003", "item": "M2-D1", "item_kind": "knowledge", "item_index": 2, "format": "choice", "difficulty": 1, "title": "箱ひげ図の読み取り", "variables": {"q": {"type": "int", "min": 1, "max": 4}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "箱ひげ図の「箱」の左端は何を表しますか。", "2": "箱ひげ図の「箱」の中の線は何を表しますか。", "3": "箱ひげ図の「ひげ」の両端は何を表しますか。", "4": "箱ひげ図の箱の横の長さは何を表しますか。"}, "correct_by_case": {"1": "第1四分位数", "2": "中央値（第2四分位数）", "3": "最小値と最大値", "4": "四分位範囲"}, "distractors_by_case": {"1": ["最小値", "中央値", "平均値"], "2": ["平均値", "最頻値", "第1四分位数"], "3": ["第1四分位数と第3四分位数", "平均値と中央値", "度数の合計"], "4": ["範囲", "平均値", "データの個数"]}, "explanation": "箱ひげ図は、最小値・第1四分位数・中央値・第3四分位数・最大値の5つの値で\nデータの分布を表したグラフです。箱の長さが四分位範囲を表します。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-D1-004', 'M2-D1-K1', 'choice', 1, '四分位数の用語', '{"id": "T-M2-D1-004", "item": "M2-D1", "item_kind": "knowledge", "item_index": 1, "format": "choice", "difficulty": 1, "title": "四分位数の用語", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "データを小さい順に並べて4等分する位置の値を何といいますか。", "2": "第2四分位数は、別の言い方では何ですか。", "3": "四分位範囲が小さいことは、何を意味しますか。"}, "correct_by_case": {"1": "四分位数", "2": "中央値", "3": "中央付近にデータが集まっている"}, "distractors_by_case": {"1": ["階級値", "相対度数", "累積度数"], "2": ["平均値", "最頻値", "範囲"], "3": ["データの個数が少ない", "平均値が小さい", "最大値が小さい"]}, "explanation": "四分位数はデータを4等分する位置の値で、第2四分位数は中央値と同じです。\n四分位範囲が小さいほど、中央付近にデータが集中しているといえます。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-D1-005', 'M2-D1-T1', 'choice', 2, '分布の比較と判断', '{"id": "T-M2-D1-005", "item": "M2-D1", "item_kind": "thinking", "item_index": 1, "format": "choice", "difficulty": 2, "title": "分布の比較と判断", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "2つの班の記録を比べるとき、箱ひげ図を使うとよいのはなぜですか。", "2": "箱ひげ図で、箱が右寄りにある集団について言えることはどれですか。", "3": "「平均値が高いほうが優れている」と結論づけるのが危ういのはなぜですか。"}, "correct_by_case": {"1": "複数の分布を並べて比べやすいから", "2": "大きい値のほうにデータが寄っている", "3": "散らばりのようすが分からないから"}, "distractors_by_case": {"1": ["平均値だけが分かるから", "個々の値がすべて分かるから", "計算しなくてよいから"], "2": ["データの個数が多い", "平均値が必ず中央値と等しい", "最大値が小さい"], "3": ["平均値は計算できないから", "中央値のほうが必ず正しいから", "データが少ないと平均は出せないから"]}, "explanation": "箱ひげ図は複数の集団の分布を並べて比較するのに適しています。\n代表値だけでなく散らばりのようすも見て、批判的に判断することが大切です。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-D2-001', 'M2-D2-K2', 'numeric', 2, '2つのさいころと場合の数', '{"id": "T-M2-D2-001", "item": "M2-D2", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "2つのさいころと場合の数", "variables": {"s": {"type": "int", "min": 2, "max": 7}}, "constraints": [], "derived": {"ans": "s - 1"}, "body": "大小2つのさいころを同時に投げます。\n出る目の和が {s} になる場合は何通りありますか。", "answers": {"通り": "ans"}, "explanation": "和が {s} になる組み合わせを、大きいさいころの目を基準に数えます。\n大の目が 1 から {ans} までのそれぞれについて小の目が1通りに決まるので、{ans}通りです。\n（起こりうる場合は全部で 6 × 6 = 36通りです。）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-D2-002', 'M2-D2-K2', 'numeric', 1, 'くじを引く確率', '{"id": "T-M2-D2-002", "item": "M2-D2", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 1, "title": "くじを引く確率", "variables": {"a": {"type": "int", "min": 1, "max": 19}}, "constraints": [], "derived": {"n": "20", "ans": "a * 5"}, "body": "{n}本のくじの中に当たりが {a}本あります。\nこの中から1本引くとき、当たりを引く確率を百分率（％）で答えなさい。", "answers": {"確率": "ans"}, "explanation": "どのくじを引くことも同様に確からしいので、\n確率は （当たりの本数）÷（全部の本数）= {a} ÷ {n} です。\n百分率にすると {ans}％ です。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-D2-003', 'M2-D2-K1', 'choice', 1, '場合の数と確率', '{"id": "T-M2-D2-003", "item": "M2-D2", "item_kind": "knowledge", "item_index": 1, "format": "choice", "difficulty": 1, "title": "場合の数と確率", "variables": {"q": {"type": "int", "min": 1, "max": 4}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "起こりうる場合が全部で n 通りあり、どれも同様に確からしいとき、\nことがらAの起こる確率はどう求めますか。", "2": "「同様に確からしい」とはどういう意味ですか。", "3": "必ず起こることがらの確率はいくつですか。", "4": "決して起こらないことがらの確率はいくつですか。"}, "correct_by_case": {"1": "（Aが起こる場合の数）÷ n", "2": "どの場合が起こることも同じ程度に期待できる", "3": "1", "4": "0"}, "distractors_by_case": {"1": ["n ÷（Aが起こる場合の数）", "（Aが起こる場合の数）× n", "n -（Aが起こる場合の数）"], "2": ["どの場合も必ず起こる", "回数を数えれば同じ数になる", "確率が1である"], "3": ["0", "0.5", "100"], "4": ["1", "0.5", "-1"]}, "explanation": "同様に確からしいとき、確率は （あることがらが起こる場合の数）÷（起こりうるすべての場合の数）\nで求められます。確率は0以上1以下で、必ず起こるとき1、決して起こらないとき0です。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-D2-004', 'M2-D2-T1', 'choice', 2, '確率の求め方を考える', '{"id": "T-M2-D2-004", "item": "M2-D2", "item_kind": "thinking", "item_index": 1, "format": "choice", "difficulty": 2, "title": "確率の求め方を考える", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "2枚の硬貨を投げるとき、起こりうる場合は何通りとして数えるのが正しいですか。", "2": "大小2つのさいころを投げるとき、起こりうる場合は何通りですか。", "3": "多数回の試行で求めた確率と、場合の数から求めた確率の関係はどれですか。"}, "correct_by_case": {"1": "（表,表）（表,裏）（裏,表）（裏,裏）の4通り", "2": "36通り", "3": "試行回数を増やすほど近づく"}, "distractors_by_case": {"1": ["表2枚・1枚・0枚の3通り", "表と裏の2通り", "数えられない"], "2": ["12通り", "21通り", "6通り"], "3": ["いつも同じ値になる", "まったく別のものである", "多数回の試行のほうが必ず正確"]}, "explanation": "確率を求めるときは、同様に確からしい場合をもれなく重複なく数えることが大切です。\n2枚の硬貨は区別して4通り、大小2つのさいころは 6 × 6 = 36通りと数えます。", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-D2-005', 'M2-D2-T2', 'numeric', 2, '起こらない確率', '{"id": "T-M2-D2-005", "item": "M2-D2", "item_kind": "thinking", "item_index": 2, "format": "numeric", "difficulty": 2, "title": "起こらない確率", "variables": {"a": {"type": "int", "min": 1, "max": 19}}, "constraints": [], "derived": {"n": "20", "hazure": "20 - a", "ans": "(20 - a) * 5"}, "body": "{n}本のくじの中に当たりが {a}本あります。\nこの中から1本引くとき、はずれる確率を百分率（％）で答えなさい。", "answers": {"確率": "ans"}, "explanation": "はずれのくじは {n} - {a} = {hazure}（本）です。\n確率は {hazure} ÷ {n} なので、百分率にすると {ans}％ です。\n（当たる確率とはずれる確率をたすと100％になります。）", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A1-001', 'M1-A1-K2', 'numeric', 1, '正負の数の加法', '{"id": "T-M1-A1-001", "item": "M1-A1", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 1, "title": "正負の数の加法", "variables": {"a": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "b": {"type": "int", "min": -9, "max": 9, "exclude": [0]}}, "constraints": ["a + b != 0"], "derived": {"ans": "a + b"}, "body": "次の計算をしなさい。\n{a} + ({b})\n", "answers": {"答え": "ans"}, "explanation": "同符号の2数の和は、絶対値の和に共通の符号を付けます。\n異符号の2数の和は、絶対値の差に絶対値の大きい方の符号を付けます。\n{a} + ({b}) = {ans}\n", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A2-001', 'M2-A2-K3', 'numeric', 2, '連立方程式（加減法）', '{"id": "T-M2-A2-001", "item": "M2-A2", "item_kind": "knowledge", "item_index": 3, "format": "numeric", "difficulty": 2, "title": "連立方程式（加減法）", "variables": {"x0": {"type": "int", "min": -5, "max": 5}, "y0": {"type": "int", "min": -5, "max": 5, "exclude": [0]}, "a1": {"type": "int", "min": 1, "max": 4}, "b1": {"type": "int", "min": 1, "max": 4}, "a2": {"type": "int", "min": 1, "max": 4}, "b2": {"type": "int", "min": -4, "max": -1}}, "constraints": ["a1 * b2 - a2 * b1 != 0", "x0 != y0"], "derived": {"c1": "a1 * x0 + b1 * y0", "c2": "a2 * x0 + b2 * y0"}, "body": "次の連立方程式を解きなさい。\n{a1}x + {b1}y = {c1}\n{a2}x + ({b2})y = {c2}\n", "answers": {"x": "x0", "y": "y0"}, "explanation": "加減法で文字を消去して解きます。\n2つの式を組み合わせて y（または x）を消去し、残った一次方程式を解くと\nx = {x0} が得られます。これを一方の式に代入すると y = {y0} となります。\n答え: x = {x0}, y = {y0}\n", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-B2-001', 'M2-B2-K1', 'choice', 1, '三角形の合同条件（穴埋め選択）', '{"id": "T-M2-B2-001", "item": "M2-B2", "item_kind": "knowledge", "item_index": 1, "format": "choice", "difficulty": 1, "title": "三角形の合同条件（穴埋め選択）", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "三角形の合同条件について、□にあてはまるものを選びなさい。\n「3組の□がそれぞれ等しいとき、2つの三角形は合同である。」\n", "2": "三角形の合同条件について、□にあてはまるものを選びなさい。\n「2組の辺とその□がそれぞれ等しいとき、2つの三角形は合同である。」\n", "3": "三角形の合同条件について、□にあてはまるものを選びなさい。\n「1組の辺とその□がそれぞれ等しいとき、2つの三角形は合同である。」\n"}, "correct_by_case": {"1": "辺", "2": "間の角", "3": "両端の角"}, "distractors_by_case": {"1": ["角", "間の角", "両端の角"], "2": ["両端の角", "対角", "辺"], "3": ["間の角", "対角", "辺"]}, "explanation": "三角形の合同条件は次の3つです。\n1. 3組の辺がそれぞれ等しい（三辺相等）\n2. 2組の辺とその間の角がそれぞれ等しい（二辺夾角相等）\n3. 1組の辺とその両端の角がそれぞれ等しい（一辺両端角相等）\n", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-C1-001', 'M2-C1-K1', 'numeric', 1, '一次関数の変化の割合', '{"id": "T-M2-C1-001", "item": "M2-C1", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 1, "title": "一次関数の変化の割合", "variables": {"m": {"type": "int", "min": -4, "max": 4, "exclude": [0]}, "n": {"type": "int", "min": -5, "max": 5}, "x1": {"type": "int", "min": -4, "max": 2}, "d": {"type": "int", "min": 1, "max": 5}}, "constraints": [], "derived": {"x2": "x1 + d", "y1": "m * x1 + n", "y2": "m * (x1 + d) + n"}, "body": "ある一次関数について、x = {x1} のとき y = {y1}、x = {x2} のとき y = {y2} です。\nこの一次関数の変化の割合を求めなさい。\n", "answers": {"変化の割合": "m"}, "explanation": "変化の割合 = (yの増加量) ÷ (xの増加量) です。\nyの増加量: {y2} - ({y1})\nxの増加量: {x2} - ({x1}) = {d}\nよって 変化の割合 = {m}\n", "status": "draft"}'::jsonb, 'draft') on conflict (id) do update set item_id = excluded.item_id, format = excluded.format, difficulty = excluded.difficulty, title = excluded.title, spec = excluded.spec;
